import { action } from "solid-js";
export const runStep = (cb) => action(function* () { cb(); })();
export const runWith = (o) => action(function* () { o.run(); })();
export const runAll = (cbs) => action(function* () { for (const cb of cbs) cb(); })();
export const Pkg = (props) => { action(function* () { props.render?.(); if (typeof props.children === "function") props.children(); })(); return null; };
export const runGet = (get) => action(function* () { get()(); })();
export const config = {};
export const runConfig = () => action(function* () { config.onStep?.(); })();
export const runNs = (ns) => action(function* () { for (const k in ns) ns[k](); })();
export const Frame = (props) => { action(function* () { void props.children; })(); return null; };
